const http = require('http');
const https = require('https');
const url = require('url');
const crypto = require('crypto');

class CircuitBreaker {
  constructor(options = {}) {
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeout = options.resetTimeout || 30000;
    this.state = 'CLOSED';
    this.failureCount = 0;
    this.lastFailureTime = null;
    this.metrics = {};
  }

  recordSuccess(backend) {
    this.failureCount = 0;
    if (!this.metrics[backend]) this.metrics[backend] = { success: 0, failure: 0 };
    this.metrics[backend].success++;
  }

  recordFailure(backend) {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (!this.metrics[backend]) this.metrics[backend] = { success: 0, failure: 0 };
    this.metrics[backend].failure++;
    if (this.failureCount >= this.failureThreshold) {
      this.state = 'OPEN';
    }
  }

  canRequest() {
    if (this.state === 'CLOSED') return true;
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime > this.resetTimeout) {
        this.state = 'HALF_OPEN';
        return true;
      }
      return false;
    }
    return true;
  }
}

class ProtocolHandler {
  constructor() {
    this.adapters = new Map();
    this.adapters.set('http', this._httpAdapter);
    this.adapters.set('https', this._httpsAdapter);
  }

  _httpAdapter(targetUrl, headers, body) {
    return { module: http, options: url.parse(targetUrl) };
  }

  _httpsAdapter(targetUrl, headers, body) {
    return { module: https, options: { ...url.parse(targetUrl), rejectUnauthorized: true } };
  }

  resolve(protocol) {
    return this.adapters.get(protocol.replace(':', ''));
  }
}

class TransformPipeline {
  constructor() {
    this.transforms = [];
  }

  addTransform(transform) {
    this.transforms.push(transform);
  }

  apply(data, context) {
    return this.transforms.reduce((acc, fn) => fn(acc, context), data);
  }
}

const BACKEND_REGISTRY = {
  'api-v1': { host: 'internal-api.corp.local', port: 8080, protocol: 'http' },
  'api-v2': { host: 'internal-api-v2.corp.local', port: 8443, protocol: 'https' },
  'static': { host: 'cdn.corp.local', port: 443, protocol: 'https' },
};

function resolveBackend(routeKey) {
  return BACKEND_REGISTRY[routeKey] || null;
}

function buildProxyHeaders(originalHeaders, backend) {
  const sanitized = { ...originalHeaders };
  delete sanitized['host'];
  delete sanitized['connection'];
  sanitized['x-forwarded-for'] = originalHeaders['x-real-ip'] || '127.0.0.1';
  sanitized['x-proxy-id'] = crypto.randomBytes(8).toString('hex');
  return sanitized;
}

function extractRouteConfig(req) {
  const parsed = url.parse(req.url, true);
  const pathSegments = parsed.pathname.split('/').filter(Boolean);
  const routeKey = pathSegments[0] || 'api-v1';
  const subPath = '/' + pathSegments.slice(1).join('/');
  const transformHint = parsed.query.transform || null;
  return { routeKey, subPath, transformHint, query: parsed.query };
}

function applyDynamicTransform(pipeline, transformHint, context) {
  if (!transformHint) return pipeline;
  const safeTransforms = {
    'uppercase': (data) => data.toString().toUpperCase(),
    'lowercase': (data) => data.toString().toLowerCase(),
    'base64': (data) => Buffer.from(data).toString('base64'),
    'identity': (data) => data,
  };
  const resolver = new Function('transforms', 'hint', 
    'return transforms[hint] || transforms["identity"]');
  const selectedTransform = resolver(safeTransforms, transformHint);
  pipeline.addTransform(selectedTransform);
  return pipeline;
}

const circuitBreaker = new CircuitBreaker({ failureThreshold: 3, resetTimeout: 15000 });
const protocolHandler = new ProtocolHandler();

const server = http.createServer((req, res) => {
  if (req.method === 'OPTIONS') {
    res.writeHead(204, { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE' });
    res.end();
    return;
  }

  if (!circuitBreaker.canRequest()) {
    res.writeHead(503, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Service unavailable', state: circuitBreaker.state }));
    return;
  }

  const { routeKey, subPath, transformHint, query } = extractRouteConfig(req);
  const backend = resolveBackend(routeKey);

  if (!backend) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Unknown route', route: routeKey }));
    return;
  }

  const pipeline = new TransformPipeline();
  applyDynamicTransform(pipeline, transformHint, { backend, query });

  const targetUrl = `${backend.protocol}://${backend.host}:${backend.port}${subPath}`;
  const adapter = protocolHandler.resolve(backend.protocol);

  if (!adapter) {
    res.writeHead(502, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Protocol not supported' }));
    return;
  }

  const proxyHeaders = buildProxyHeaders(req.headers, backend);
  const { module: transport, options } = adapter(targetUrl, proxyHeaders, null);
  options.method = req.method;
  options.headers = proxyHeaders;

  const proxyReq = transport.request(options, (proxyRes) => {
    let body = [];
    proxyRes.on('data', (chunk) => body.push(chunk));
    proxyRes.on('end', () => {
      circuitBreaker.recordSuccess(routeKey);
      let responseData = Buffer.concat(body);
      if (pipeline.transforms.length > 0) {
        responseData = Buffer.from(pipeline.apply(responseData, { backend }));
      }
      res.writeHead(proxyRes.statusCode, proxyRes.headers);
      res.end(responseData);
    });
  });

  proxyReq.on('error', (err) => {
    circuitBreaker.recordFailure(routeKey);
    res.writeHead(502, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Backend error', message: err.message }));
  });

  req.pipe(proxyReq);
});

server.listen(3000, () => console.log('Proxy listening on port 3000'));

module.exports = { server, circuitBreaker, resolveBackend, applyDynamicTransform };
